param(
    [string]$ProjectPath = (Get-Location).Path
)

$ErrorActionPreference = "Stop"
$ProjectPath = (Resolve-Path -LiteralPath $ProjectPath).Path
$TimeStamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupRoot = Join-Path $ProjectPath "backup_atualizacao_propostas_$TimeStamp"
$LogPath = Join-Path $ProjectPath "atualizacao_propostas_$TimeStamp.log"

function Write-Log {
    param([string]$Message, [string]$Color = "Gray")
    $line = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] $Message"
    Write-Host $line -ForegroundColor $Color
    Add-Content -LiteralPath $LogPath -Value $line -Encoding UTF8
}

function Find-UniqueFile {
    param([string]$FileName)
    $ignored = @('node_modules', '.git', '.venv', 'venv', '__pycache__', 'dist', 'build')
    $matches = Get-ChildItem -LiteralPath $ProjectPath -Recurse -File -Filter $FileName -ErrorAction SilentlyContinue | Where-Object {
        $full = $_.FullName
        -not ($ignored | Where-Object { $full -match "[\\/]$([regex]::Escape($_))[\\/]" }) -and
        $full -notlike "$BackupRoot*"
    }
    if ($matches.Count -eq 0) { throw "Arquivo nao encontrado no projeto: $FileName" }
    if ($matches.Count -gt 1) {
        $list = ($matches.FullName -join [Environment]::NewLine)
        throw "Mais de um arquivo '$FileName' foi encontrado. Remova copias duplicadas ou execute na pasta correta:`n$list"
    }
    return $matches[0].FullName
}

function Install-EmbeddedFile {
    param([string]$FileName, [string]$Base64Content)
    $target = Find-UniqueFile -FileName $FileName
    $relative = $target.Substring($ProjectPath.Length).TrimStart('\','/')
    $backup = Join-Path $BackupRoot $relative
    $backupDir = Split-Path -Parent $backup
    New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
    Copy-Item -LiteralPath $target -Destination $backup -Force
    [System.IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($Base64Content))
    Write-Log "Atualizado: $relative" "Green"
}

Write-Host ""
Write-Host "ATUALIZACAO DO FLUXO DE PROPOSTAS E PERFIS" -ForegroundColor Cyan
Write-Host "Projeto: $ProjectPath" -ForegroundColor DarkGray
Write-Host ""

try {
    New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
    Write-Log "Backup sendo criado em: $BackupRoot" "Cyan"

    Install-EmbeddedFile 'access_control.py' ''
    Install-EmbeddedFile 'proposal_edit.html' ''
    Install-EmbeddedFile 'proposal_detail.html' ''
    Install-EmbeddedFile 'portal_profiles.html' ''
    Install-EmbeddedFile 'proposal-editor.css' ''

    $backend = Find-UniqueFile -FileName 'access_control.py'
    $python = Get-Command python -ErrorAction SilentlyContinue
    if (-not $python) { $python = Get-Command py -ErrorAction SilentlyContinue }
    if ($python) {
        if ($python.Name -eq 'py.exe' -or $python.Name -eq 'py') {
            & $python.Source -3 -m py_compile $backend
        } else {
            & $python.Source -m py_compile $backend
        }
        if ($LASTEXITCODE -ne 0) { throw "A validacao Python falhou." }
        Write-Log "Sintaxe do backend validada com sucesso." "Green"
    } else {
        Write-Log "Python nao localizado no PATH. Os arquivos foram instalados, mas a validacao automatica foi ignorada." "Yellow"
    }

    Write-Log "Atualizacao concluida com sucesso." "Cyan"
    Write-Host ""
    Write-Host "Funcoes instaladas:" -ForegroundColor Cyan
    Write-Host "- editar e reenviar propostas rejeitadas"
    Write-Host "- destacar campos e acessos alterados para o administrador"
    Write-Host "- filtrar perfis por nome, situacao, origem e departamento"
    Write-Host "- excluir, como ADMIN, somente perfis criados pelo sistema"
    Write-Host ""
    Write-Host "Backup: $BackupRoot" -ForegroundColor Yellow
    Write-Host "Log: $LogPath" -ForegroundColor DarkGray
    Write-Host "Reinicie o sistema e pressione Ctrl + F5 no navegador." -ForegroundColor Cyan
}
catch {
    Write-Log "ERRO: $($_.Exception.Message)" "Red"
    Write-Host "Nenhum backup foi apagado. Se algum arquivo ja tiver sido alterado, restaure-o pela pasta:" -ForegroundColor Yellow
    Write-Host $BackupRoot -ForegroundColor Yellow
    exit 1
}
